mapper.select:
SELECT o.id, o.order_no, o.user_id, o.store_id, o.merchant_id, s.name as store_name, o.status as status_code, o.remark, o.total_product_price, o.total_discount_amount, o.final_paid_price, CASE WHEN (SELECT COUNT(1) FROM order_address_snapshots oas WHERE oas.order_id = o.id AND oas.detail_address IS NOT NULL AND oas.detail_address != '' AND oas.is_deleted = 0) > 0 THEN 'LOCAL_DELIVERY' ELSE 'IN_STORE' END as fulfillment_mode, CASE WHEN (SELECT COUNT(1) FROM order_address_snapshots oas WHERE oas.order_id = o.id AND oas.detail_address IS NOT NULL AND oas.detail_address != '' AND oas.is_deleted = 0) > 0 THEN '本地配送' ELSE '到店核销' END as fulfillment_mode_description, CASE WHEN o.payment_method = 'WECHAT_PAY' THEN 1 WHEN o.payment_method = 'ALIPAY' THEN 2 WHEN o.payment_method = 'BANK_CARD' THEN 3 END as pay_method, CASE WHEN o.payment_method = 'WECHAT_PAY' THEN '微信支付' WHEN o.payment_method = 'ALIPAY' THEN '支付宝' WHEN o.payment_method = 'BANK_CARD' THEN '银行卡' ELSE '其他' END as payment_method_description, o.payment_time, o.verification_code, o.created_by, o.completion_time, o.created_time, o.updated_time FROM orders o LEFT JOIN stores s ON o.store_id = s.id WHERE o.is_deleted = 0
AND o.status = #{q.status}
AND o.store_id = #{q.storeId}
AND o.user_id = #{q.userId}
AND o.order_no = #{q.orderNo}
AND o.created_time >= #{q.createdStart}
AND o.created_time <= #{q.createdEnd}
ORDER BY o.created_time DESC

SELECT
    o.user_id,
    o.store_id,
    o.created_by,
    o.merchant_id
FROM orders o
WHERE o.is_deleted = 0

    AND o.status = #{q.status}


    AND o.store_id = #{q.storeId}


    AND o.user_id = #{q.userId}


    AND o.order_no = #{q.orderNo}


    AND o.created_time >= #{q.createdStart}


    AND o.created_time <= #{q.createdEnd}

